class HarnessComic extends ComicSource {
  name = "Harness Comic";
  key = "harness_comic";
  version = "1.0.0";
  url = "http://localhost:8123";

  settings = {
    domains: { title: "主域名", type: "select", default: "localhost:8123", options: [{ value: "localhost:8123" }] },
  };

  explore = [
    {
      title: "推荐",
      type: "singlePageWithMultiPart",
      load: async () => {
        const res = await Network.get(this.url + "/test/fixtures/comic-search.html");
        const doc = new HtmlDocument(res.body);
        const comics = doc.querySelectorAll("div#main > div.comic-card").map((card) => ({
          id: card.querySelector("a").attributes["href"],
          title: card.querySelector("h3").text,
          cover: card.querySelector("img").attributes["src"],
          subTitle: card.querySelector("span.author").text,
          description: card.querySelector("span.desc").text,
          tags: card.querySelector("span.tags").text.split(","),
        }));
        return { "推荐": comics };
      },
    },
  ];

  search = {
    load: async (keyword, options, page) => {
      const res = await Network.get(this.url + "/test/fixtures/comic-search.html?q=" + encodeURIComponent(keyword));
      const doc = new HtmlDocument(res.body);
      const comics = doc.querySelectorAll("div#main > div.comic-card").map((card) => ({
        id: card.querySelector("a").attributes["href"],
        title: card.querySelector("h3").text,
        cover: card.querySelector("img").attributes["src"],
        subTitle: card.querySelector("span.author").text,
          description: card.querySelector("span.desc").text,
          tags: card.querySelector("span.tags").text.split(","),
        }));
        return { comics, maxPage: 1 };
    },
  };

  comic = {
    loadInfo: async (id) => {
      const res = await Network.get(this.url + id);
      const doc = new HtmlDocument(res.body);
      const chapters = new Map();
      doc.querySelectorAll("ul.chapters > li > a").forEach((node) => {
        chapters.set(node.attributes["data-id"], node.text);
      });
      return new ComicDetails({ title: "星海 & 山海", chapters });
    },
    loadEp: async (comicId, epId) => {
      const res = await Network.get(this.url + "/test/fixtures/comic-pages.html");
      const doc = new HtmlDocument(res.body);
      return {
        images: doc.querySelectorAll("div.reader img").map((img) => img.attributes["data-src"]),
      };
    },
  };
}
